def transform(grid):
    g = np.array(grid).copy()
    emit(g, "Start from a copy of the input; the only edit is recolouring every 7 to 5.")
    for y in range(g.shape[0]):
        if (g[y] == 7).any():
            g[y][g[y] == 7] = 5
            emit(g, f"Row {y}: every 7 in this row becomes 5; other colours are untouched.")
    emit(g, "All 7s have been replaced by 5; this is the final output.")
    return g
